function authenticate() {
    global $username, $password, $host_file;
    $URL = $host_file . 'sessions';

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_HTTP_VERSION, CURL_HTTP_VERSION_1_1);
    curl_setopt($ch, CURLOPT_URL, $URL);
    curl_setopt($ch, CURLOPT_HTTPAUTH, CURLAUTH_BASIC);
    curl_setopt($ch, CURLOPT_HTTPHEADER, array("Content-Type: application/json"));
    curl_setopt($ch, CURLOPT_USERPWD, "$username:$password");
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, '{}');
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
    $result = curl_exec($ch);
    if ($result === FALSE) die('Error CURL: ' . curl_error($ch));
    curl_close($ch);

    $response = json_decode($result, true);
    if ($response['messages'][0]['message'] === 'OK') {
        return $response['response']['token'];
    } else {
        die('Error en autenticacion: ' . $response['messages'][0]['message']);
    }
}

function findRecordByFields($token, $layout, $criterios, $sort = []) {
    global $host_file;
    $URL = $host_file . 'layouts/' . urlencode($layout) . '/_find?portal=false';

    $data = ['query' => [ $criterios ]];
    if (!empty($sort)) {
        $data['sort'] = $sort;
    }
    $jsonData = json_encode($data);

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_HTTP_VERSION, CURL_HTTP_VERSION_1_1);
    curl_setopt($ch, CURLOPT_URL, $URL);
    curl_setopt($ch, CURLOPT_HTTPHEADER, array(
        "Content-Type: application/json",
        "Authorization: Bearer $token"
    ));
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $jsonData);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
    $result = curl_exec($ch);
    if ($result === FALSE) die('Error en busqueda: ' . curl_error($ch));
    curl_close($ch);
    return json_decode($result, true);
}

