document.getElementById("formEvidencia").addEventListener("submit", function (e) {
    var campoUbicacion = document.getElementById("ubicacion");

    // Si ya hay ubicacion, se envia normal
    if (campoUbicacion.value !== "") {
        return true;
    }

    // Si no, detenemos el envio y pedimos el GPS primero
    e.preventDefault();
    var formulario = this;

    navigator.geolocation.getCurrentPosition(
        function (posicion) {
            var lat = posicion.coords.latitude;
            var lon = posicion.coords.longitude;
            campoUbicacion.value = lat + "," + lon;
            formulario.submit();   // ahora si, ya con la ubicacion
        },
        function (error) {
            formulario.submit();   // si falla el GPS, se envia igual
        }
    );
});
